#include "../models/contact_birth/BirthLaw.h"
#include <iostream>
using namespace regrip_integrated;
void require(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(){try{std::cout<<std::setprecision(17);Pose object,point;point.p={0,1.01,.02};V before{0,1.03,0};auto birth=regrip_birthlaw::evaluate(point,object,{},before,2,1,5,.02,1,1,100);double e=birth.next.elastic[2];double internalWork=-e*e,derivedLoss=.5*e*e;require(std::abs(internalWork+birth.elasticEnergy+derivedLoss)<1e-14,"flat born stick discrete work identity");
 auto slide=regrip_birthlaw::evaluate(point,object,{},before,2,1,5,.02,1,1,.1);double endpointWork=slide.next.elastic[2]*.01;require(std::abs(endpointWork-slide.elasticEnergy-slide.plasticDissipation-.5*dot(slide.next.elastic,slide.next.elastic))<1e-14,"born slip derived discrete work");
 Pose separated=point;separated.p[1]=2;auto death=regrip_birthlaw::value(separated,object,birth.next,point.p,2,1,5,.02,1,1,100);require(!death.next.active&&std::abs(death.releaseDissipation-birth.elasticEnergy)<1e-14,"instantaneous detachment inventory, not Coulomb friction");auto again=regrip_birthlaw::value(point,object,{},separated.p,2,1,5,.02,1,1,100);require(again.next.active,"fresh recontact");
 Q rotation=exp(V{.7,-.5,.8});V translation{1,2,3};Pose rotatedObject,rotatedPoint;rotatedObject.q=rotation;rotatedObject.p=translation;rotatedPoint.p=add(translation,rotate(rotation,point.p));auto transformed=regrip_birthlaw::evaluate(rotatedPoint,rotatedObject,{},before,2,1,5,.02,1,1,100);double objective=0;for(int offset:{0,6,9}){auto expected=rotate(rotation,V{birth.wrench.force[offset],birth.wrench.force[offset+1],birth.wrench.force[offset+2]});for(int j=0;j<3;++j)objective=std::max(objective,std::abs(expected[j]-transformed.wrench.force[offset+j]));}require(objective<1e-12,"finite common frame rotation objectivity");
 bool grazing=false;try{Pose p;p.p={0,1.02-1e-12,1};regrip_birthlaw::evaluate(p,object,{},V{0,1.02+1e-12,0},2,1,5,.02,1,1,100);}catch(const std::invalid_argument&){grazing=true;}require(grazing,"grazing implicit derivative rejected");
 double equivalence=0;for(int i=0;i<100;++i){V a{1.04,.01*i/100,0},b{1.01,.02,.03};auto after=regrip_history::constantV<regrip_history::First>(b);after[0]=after[0]+regrip_history::First::variable(0);auto original=regrip_birth::firstContact(a,after,0,1,5,.02),fast=regrip_birthfast::increment(a,after,0,1,5,.02);equivalence=std::max(equivalence,std::abs(original.crossingFraction-fast.crossingFraction));for(int j=0;j<3;++j){equivalence=std::max(equivalence,std::abs(original.elastic[j].v-fast.elastic[j].v));for(int k=0;k<12;++k)equivalence=std::max(equivalence,std::abs(original.elastic[j].g[k]-fast.elastic[j].g[k]));}}require(equivalence<1e-10,"analytic/bracket root AD equivalence");
 std::cout<<"PASS birth/stick/slip/death/recontact/grazing/rotation; objectivity="<<objective<<" root_equivalence="<<equivalence<<" born_tangent_energy="<<birth.elasticEnergy<<" detachment_loss="<<death.releaseDissipation<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
